import sys
input = sys.stdin.read

def find_position(n):
    # Define directions in the spiral order
    directions = [(1, 0), (0, 1), (-1, 1), (-1, 0), (0, -1), (1, -1)]

    # Initialize starting position and step length
    x, y = 0, 0
    step_length = 1
    move_count = 0

    while move_count < n:
        for direction in directions:
            for _ in range(step_length):
                if move_count >= n:
                    return (x, y)
                x += direction[0]
                y += direction[1]
                move_count += 1
            if direction == (-1, 1) or direction == (1, -1):
                step_length += 1  # Increase the step length after completing a cycle

    return (x, y)

# Read input
n = int(input().strip())

# Find the current position after n moves
x, y = find_position(n)

# Print the result
print(x, y)

